func testLLMRiskEvaluationToManyAddOpRiskEvaluationLLMOrderIntents(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LLMRiskEvaluation
	var b, c, d, e LLMOrderIntent

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, llmRiskEvaluationDBTypes, false, strmangle.SetComplement(llmRiskEvaluationPrimaryKeyColumns, llmRiskEvaluationColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LLMOrderIntent{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, llmOrderIntentDBTypes, false, strmangle.SetComplement(llmOrderIntentPrimaryKeyColumns, llmOrderIntentColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*LLMOrderIntent{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddRiskEvaluationLLMOrderIntents(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ID != first.RiskEvaluationID {
			t.Error("foreign key was wrong value", a.ID, first.RiskEvaluationID)
		}
		if a.ID != second.RiskEvaluationID {
			t.Error("foreign key was wrong value", a.ID, second.RiskEvaluationID)
		}

		if first.R.RiskEvaluation != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.RiskEvaluation != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.RiskEvaluationLLMOrderIntents[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.RiskEvaluationLLMOrderIntents[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.RiskEvaluationLLMOrderIntents().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
